<div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><div><h1 class="h2">Manage documents</h1><p class="text-secondary">Private supporting documents for your membership application.</p></div><a class="btn btn-outline-secondary" href="<?=e(url('/membership/application'))?>">Back to application</a></div><?php if(!$application):?><div class="alert alert-warning">Create a membership application before uploading documents.</div><?php else:?><div class="alert alert-info">Final document requirements are pending confirmation. Uploads are private and begin as Pending. Malware scanning is not currently configured.</div><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">Upload document</h2><form method="post" enctype="multipart/form-data" action="<?=e(url('/membership/application/documents/upload'))?>"><?=csrf_field()?><div class="row g-3"><div class="col-md-5"><label class="form-label" for="document_type_id">Document type</label><select class="form-select" id="document_type_id" name="document_type_id" required><option value="">Select type</option><?php foreach($types as $type):?><option value="<?=e($type['id'])?>"><?=e($type['name'])?> — <?=$type['required']?'Required':'Optional'?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label" for="document">PDF, JPEG or PNG</label><input class="form-control" id="document" name="document" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required><div class="form-text">Maximum 5 MB. File input is never retained after an error.</div></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Upload</button></div></div></form></div></div><div class="row g-3 mb-4"><?php foreach($counts as $key=>$count):?><div class="col-4"><div class="card"><div class="card-body"><strong><?=e($count)?></strong> <?=e(ucfirst($key))?></div></div></div><?php endforeach;?></div><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Document</th><th>File</th><th>Size</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$documents):?><tr><td colspan="5" class="text-center p-5">No documents uploaded.</td></tr><?php endif;?><?php foreach($documents as $document):?><tr><td><?=e($document['document_type_name'])?><br><small><?=e($document['document_reference'])?></small></td><td><?=e($document['original_filename'])?><br><small><?=e(date('j M Y',strtotime($document['uploaded_at'])))?></small></td><td><?=e(number_format($document['byte_size']/1024,1))?> KB</td><td><span class="badge text-bg-secondary"><?=e($documentStatuses->label($document['verification_status']))?></span><?php if($document['rejection_reason']):?><div class="small text-danger"><?=e($document['rejection_reason'])?></div><?php endif;?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=e(url('/membership/application/documents/'.$document['document_reference'].'/download'))?>">Download</a><?php if(in_array($document['verification_status'],['pending','rejected'],true)):?><form class="mt-2" method="post" enctype="multipart/form-data" action="<?=e(url('/membership/application/documents/'.$document['document_reference'].'/replace'))?>"><?=csrf_field()?><input class="form-control form-control-sm mb-1" name="document" type="file" accept=".pdf,.jpg,.jpeg,.png" required><button class="btn btn-sm btn-outline-warning">Replace</button></form><form class="mt-2" method="post" action="<?=e(url('/membership/application/documents/'.$document['document_reference'].'/remove'))?>" onsubmit="return confirm('Remove this document from the active checklist?')"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
